(()=>{"use strict";const t=()=>{if("function"==typeof window.qrcode)for(const t of document.querySelectorAll("[data-totp-qrcode]"))if(!t.firstChild){const e=window.qrcode(0,"H");e.addData(t.getAttribute("data-totp-qrcode")),e.make(),t.innerHTML=e.createImgTag(4)}};"loading"===document.readyState?document.addEventListener("DOMContentLoaded",t):t()})();